"use client";

// Generated by `pnpm relume:convert gallery24` from relume/source/gallery24.tsx
// (Relume Gallery 24), browser half, then finished by hand: the row slides
// only while it is pinned, and stops when the last image is centred on the
// screen, instead of sliding its own fixed width and ending on an empty screen.
import { blockDataAttribute } from "@/components/blocks/relume/block-editing";
import { BlockImage } from "@/components/blocks/relume/block-image";
import {
  MotionConfig,
  motion,
  useMotionValue,
  useScroll,
  useTransform,
} from "motion/react";
import { stegaClean } from "next-sanity";
import { useLayoutEffect, useRef } from "react";
import { resolveBlockTheme, blockSceneClassName } from "../block-boundaries";
import type { RelumeGallery24Props } from "./gallery24";

export default function RelumeGallery24Client({
  _key,
  bottom = "outer",
  editing,
  heading,
  description,
  images,
  theme,
  top = "outer",
}: Omit<RelumeGallery24Props, "_type">) {
  const dataAttribute = blockDataAttribute(editing);
  const headingId = `relume-gallery24-${stegaClean(_key)}-heading`;
  // The pinned stretch: progress runs from the moment the row sticks to the
  // moment it lets go, so the row moves only while it is pinned.
  const pinRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: pinRef,
    offset: ["start start", "end end"],
  });
  // How far the row slides: from the first image at the left edge to the
  // last image's centre on the centre of the screen, measured in pixels.
  const distance = useMotionValue(0);
  useLayoutEffect(() => {
    const stage = stageRef.current;
    const track = trackRef.current;
    if (!stage || !track) return;
    const measure = () => {
      const last = track.lastElementChild as HTMLElement | null;
      if (!last) return distance.set(0);
      // The last image's centre in the untransformed row: its offset from
      // the row's start (a difference of two rects, so the current slide
      // cancels out) plus where the row starts on the stage.
      const lastCentre =
        track.offsetLeft +
        last.getBoundingClientRect().left -
        track.getBoundingClientRect().left +
        last.offsetWidth / 2;
      distance.set(Math.max(0, lastCentre - stage.clientWidth / 2));
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(stage);
    observer.observe(track);
    return () => observer.disconnect();
  }, [distance, images?.length]);
  const x = useTransform(
    [scrollYProgress, distance],
    ([progress, d]: number[]) => -progress * d,
  );

  return (
    <MotionConfig reducedMotion="user">
      <section
        aria-labelledby={headingId}
        className={blockSceneClassName(resolveBlockTheme(theme), top, bottom)}
        data-sanity={dataAttribute?.("theme")}
      >
        <div>
          <div className="container text-center">
            <h2
              className="mb-5 typo-block-heading md:mb-6"
              data-sanity={dataAttribute?.("heading")}
              id={headingId}
            >
              {heading}
            </h2>
            {stegaClean(description)?.trim() ? (
              <p
                className="typo-body-editorial"
                data-sanity={dataAttribute?.("description")}
              >
                {description}
              </p>
            ) : null}
          </div>
        </div>

        <div ref={pinRef} className="h-[400vh] motion-reduce:h-auto!">
          <div
            ref={stageRef}
            className="sticky top-0 mt-[-10vh] flex h-screen w-screen max-w-full flex-col items-start justify-center overflow-hidden px-[5%] md:mt-0 motion-reduce:static! motion-reduce:my-0! motion-reduce:h-auto! motion-reduce:py-12!"
          >
            <motion.div
              ref={trackRef}
              style={{ x }}
              className="flex w-[150vh] items-center gap-x-6 sm:w-[200vh] md:gap-x-8 lg:w-[400vh] motion-reduce:transform-none! motion-reduce:w-full! motion-reduce:flex-col! motion-reduce:gap-y-6!"
            >
              {(images ?? []).map((image) => (
                <a key={image._key} className="inline-block max-w-full">
                  <div className="relative size-full max-w-full overflow-hidden">
                    <BlockImage
                      className="h-[80vh] max-h-[25rem] rounded-card object-cover sm:max-h-[30rem] sm:w-[90vw] md:max-h-[40rem] md:w-[80vw] lg:max-h-none"
                      dataSanity={dataAttribute?.(
                        `images[_key=="${image._key}"]`,
                      )}
                      image={image}
                    />
                  </div>
                </a>
              ))}
            </motion.div>
          </div>
        </div>
      </section>
    </MotionConfig>
  );
}
